/**
 * Default voice reference: when the user has not chosen a voice profile, optionally show the model
 * a couple of real human-written passages so it can see how a person's sentences move.
 *
 * Off unless DEFAULT_EXEMPLARS=on. It has not been measured against detectors yet (see
 * bench/README.md: run once with --exemplars off and once with --exemplars on, then compare).
 *
 * The passages live in config/human-exemplars.ts, generated by scripts/build-exemplars.ts from real
 * human text. Different requests see different passages (chosen by seed), so there is no single
 * fixed few-shot block shared by every output.
 */
import { createHash } from "crypto";
import { HUMAN_EXEMPLARS, type HumanExemplar } from "../../config/human-exemplars";
import { pickN, rng, type Register } from "../pipeline/stylePlan";

export const EXEMPLARS_PER_PROMPT = 2;

/** True only when DEFAULT_EXEMPLARS is set to "on". */
export function defaultExemplarsEnabled(raw: string | undefined = process.env.DEFAULT_EXEMPLARS): boolean {
  return (raw ?? "").trim().toLowerCase() === "on";
}

/**
 * Picks `count` passages for one generation. Same seed, same passages (so the cache stays consistent).
 * Prefers the requested register, then neutral, then anything else.
 */
export function pickExemplars(
  seed: string,
  register: Register,
  count = EXEMPLARS_PER_PROMPT,
  pool: HumanExemplar[] = HUMAN_EXEMPLARS
): HumanExemplar[] {
  const r = rng(`exemplars:${seed}`);
  const same = pool.filter((e) => e.register === register);
  const neutral = pool.filter((e) => e.register !== register && e.register === "neutral");
  const other = pool.filter((e) => e.register !== register && e.register !== "neutral");
  return [...pickN(r, same, same.length), ...pickN(r, neutral, neutral.length), ...pickN(r, other, other.length)].slice(0, count);
}

export function renderExemplarBlock(exemplars: HumanExemplar[]): string {
  if (!exemplars.length) return "";
  const passages = exemplars.map((e, i) => `Passage ${i + 1}:\n"""\n${e.text}\n"""`).join("\n");
  return [
    "",
    "",
    "Reference passages by real writers. Look only at how their sentences move: uneven lengths with no pattern, plain concrete wording, direct statements.",
    "Do NOT copy their words, phrases, names or subjects, and do not imitate their period or vocabulary. Write about the draft's own subject in plain modern English.",
    passages,
  ].join("\n");
}

/** Short fingerprint of the pool, so changing the passages changes the cache key. */
export function exemplarsTag(pool: HumanExemplar[] = HUMAN_EXEMPLARS): string {
  return "ex-" + createHash("sha1").update(pool.map((e) => `${e.id}:${e.text}`).join("|")).digest("hex").slice(0, 8);
}
